  output_typeconvert <= (7 => '0', OTHERS => '1') WHEN (sum40(32) = '0' AND sum40(31) /= '0') OR (sum40(32) = '0' AND sum40(31 DOWNTO 24) = "01111111") -- special case0
      ELSE (7 => '1', OTHERS => '0') WHEN sum40(32) = '1' AND sum40(31) /= '1'
      ELSE (resize(shift_right(sum40(32) & sum40(31 DOWNTO 23) + 1, 1), 8));

  Output_Register_process : PROCESS (clk, reset)
  BEGIN
    IF reset = '1' THEN
      output_register <= (OTHERS => '0');
    ELSIF clk'event AND clk = '1' THEN
      IF clk_enable = '1' THEN
        output_register <= output_typeconvert;
      END IF;
    END IF; 
  END PROCESS Output_Register_process;

  -- Assignment Statements
  filter_out <= std_logic_vector(output_register);
END rtl;
